s FROM combined_transactions a LEFT JOIN snitch_db.maplemonk.product_journey b ON a.sku_group = b.sku_group LEFT JOIN snitch_db.maplemonk.base_product bp ON a.sku_group = bp.sku_group left join snitch_db.maplemonk.metafields_data m on m.sku_group = a.sku_group left join sku_cogs c on c.sku_group = a.sku_group ) SELECT date, type, sku_group, CASE when category in ( \'accessories\', \'bags\', \'belts\', \'caps\', \'perfumes\', \'shoes\', \'sunglasses\' ) THEN \'long_tail\' WHEN LOWER(sku_group) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(sku_group) LIKE \'r4mbg%\' THEN \'plus_size\' WHEN UPPER(sku_group) LIKE \'4ML%\' THEN \'luxe\' WHEN UPPER(sku_group) LIKE \'4MTL%\' THEN \'luxe\' WHEN UPPER(sku_group) LIKE \'4MBGSS%\' THEN \'plus_size\' WHEN UPPER(sku_group) LIKE \'4MBGSR%\' THEN \'plus_size\' WHEN UPPER(sku_group) LIKE \'4MBGSD%\' THEN \'plus_size\' WHEN UPPER(sku_group) LIKE \'4MBGST%\' THEN \'plus_size\' WHEN UPPER(sku_group) LIKE \'SH00%\' THEN \'long_tail\' WHEN UPPER(sku_group) LIKE \'4MBL%\' THEN \'long_tail\' WHEN UPPER(sku_group) LIKE \'4MHT%\' THEN \'long_tail\' WHEN UPPER(sku_group) LIKE \'4MCP%\' THEN \'long_tail\' WHEN UPPER(sku_group) LIKE \'4MBD%\' THEN \'long_tail\' WHEN UPPER(sku_group) LIKE \'SN%\' THEN \'long_tail\' WHEN UPPER(sku_group) LIKE \'SH%\' THEN \'long_tail\' WHEN UPPER(sku_group) LIKE \'4MSFC%\' THEN \'long_tail\' WHEN UPPER(sku_group) LIKE \'4L%\' THEN \'luxe\' WHEN UPPER(sku_group) LIKE \'4B%\' THEN \'plus_size\' WHEN UPPER(sku_group) LIKE \'4%\' THEN \'snitch\' else \'Snitch\' end L1_Category, category, CASE WHEN avg(COALESCE(original_price, MRP_new)) < 500 THEN \'0-500\' WHEN avg(COALESCE(original_price, MRP_new)) < 1000 THEN \'500-1000\' WHEN avg(COALESCE(original_price, MRP_new)) < 1500 THEN \'1000-1500\' WHEN avg(COALESCE(original_price, MRP_new)) < 2000 THEN \'1500-2000\' WHEN avg(COALESCE(original_price, MRP_new)) < 3000 THEN \'2000-3000\' WHEN avg(COALESCE(original_price, MRP_new)) < 4000 THEN \'3000-4000\' WHEN avg(COALESCE(original_price, MRP_new)) < 5000 THEN \'4000-5000\' ELSE \'5000+\' END AS MRP_Bracket, SUM(gross_sales) AS gross_sales, SUM(gross_quantity * COALESCE(original_price, MRP_new)) AS mrp_sales, avg(COALESCE(original_price, MRP_new)) MRP, SUM(cancel_quantity * COALESCE(original_price, 0)) AS cancellations, SUM( CASE WHEN type = \'Marketplace\' THEN specific_return_amount ELSE return_quantity * COALESCE(original_price, 0) END ) AS returns, SUM(discount_amount) AS discount_amount, SUM(tax_amount) AS tax_amount, SUM(gross_quantity * COALESCE(cost_price, cogs, 0)) AS cogs, FROM raw_data rd LEFT JOIN (select SPLIT(sku, \'-\')[0] sku,base_price MRP_new from snitch_db.maplemonk.logic_final_item_master) pj ON SPLIT(rd.sku_group, \'-\')[0] = sku GROUP BY 1, 2, 3, 4, 5 ORDER BY date DESC, type;",
